begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(14);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18600000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-cancel-review@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18600000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18600000-0000-0000-0000-000000000002','18600000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18600000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18600000-0000-0000-0000-000000000004','18600000-0000-0000-0000-000000000001','18600000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18600000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18600000-0000-0000-0000-000000000005','18600000-0000-0000-0000-000000000001','18600000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18600000-0000-0000-0000-000000000006','18600000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18600000-0000-0000-0000-000000000007','18600000-0000-0000-0000-000000000002','Synthetic staff');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18600000-0000-0000-0000-000000000008','18600000-0000-0000-0000-000000000002','18600000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18600000-0000-0000-0000-000000000002',true,'{}','18600000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18600000-0000-0000-0000-000000000002',true,'{}','18600000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18600000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18600000-0000-0000-0000-000000000003","session_id":"18600000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_shift_cancel_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18600000-0000-0000-0000-000000000002',true,'{}','18600000-0000-0000-0000-000000000001',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('cancel186-browser','cancel186-browser','18600000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18600000-0000-0000-0000-000000000009','18600000-0000-0000-0000-000000000002','18600000-0000-0000-0000-000000000006','2026-11-02 00:00+00','2026-11-02 01:00+00','published');
select set_config('test.cancel',private.prepare_mcp_shift_cancel('18600000-0000-0000-0000-000000000002','18600000-0000-0000-0000-000000000008','cancel','synthetic')::text,true);
select set_config('test.stale',private.prepare_mcp_shift_cancel('18600000-0000-0000-0000-000000000002','18600000-0000-0000-0000-000000000008','cancel','synthetic')::text,true);
select set_config('test.delete',private.prepare_mcp_shift_cancel('18600000-0000-0000-0000-000000000002','18600000-0000-0000-0000-000000000009','soft_delete','synthetic')::text,true);
select ok(has_function_privilege('authenticated','public.get_mcp_shift_cancel_proposal(uuid)','execute') and not has_function_privilege('mcp_import','public.get_mcp_shift_cancel_proposal(uuid)','execute'),'only browser can invoke review');
select throws_ok($$select public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)$$,'42501','proposal_unavailable','OAuth cannot read browser review');
select set_config('request.jwt.claims','{"sub":"18600000-0000-0000-0000-000000000001","role":"authenticated","session_id":"cancel186-browser"}',true);
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)->>'status','confirmation_required','owner sees confirmation state');
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)->>'operation','cancel','fixed operation is returned');
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)->>'reason','synthetic','fixed reason is returned');
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)->'references'->'client'->>'name','Synthetic client','client identity shown');
select is(public.get_mcp_shift_cancel_proposal('18600000-0000-0000-0000-000000000099'),null::jsonb,'unknown proposal unavailable');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18600000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-other-review@example.invalid','x',now(),now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('cancel-other-browser','cancel-other-browser','18600000-0000-0000-0000-000000000011',now(),now()+interval '1 hour');
select set_config('request.jwt.claims','{"sub":"18600000-0000-0000-0000-000000000011","role":"authenticated","session_id":"cancel-other-browser"}',true);
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid),null::jsonb,'another user cannot see the proposal');
select set_config('request.jwt.claims','{"sub":"18600000-0000-0000-0000-000000000001","role":"authenticated","session_id":"cancel186-browser"}',true);
savepoint expiration;
update private.mcp_shift_cancel_proposals set created_at=statement_timestamp()-interval '11 minutes',expires_at=statement_timestamp()-interval '1 minute' where id=current_setting('test.cancel')::uuid;
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)->>'status','expired','expired proposal cannot be reviewed as actionable');
rollback to savepoint expiration;

update public.staffs set name='Another name' where id='18600000-0000-0000-0000-000000000007';
update public.clients set name='Renamed client' where id='18600000-0000-0000-0000-000000000006';
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)->>'status','changed','changed identity is detected');
update public.clients set name='Synthetic client' where id='18600000-0000-0000-0000-000000000006';
update private.mcp_shift_cancel_controls set enabled=false where organization_id='18600000-0000-0000-0000-000000000002';
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid),null::jsonb,'disabled control prevents reading');
update private.mcp_shift_cancel_controls set enabled=true where organization_id='18600000-0000-0000-0000-000000000002';
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18600000-0000-0000-0000-000000000004';
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid),null::jsonb,'revoked OAuth prevents reading');
update auth.oauth_consents set revoked_at=null where id='18600000-0000-0000-0000-000000000004';
select is(private.confirm_mcp_shift_cancel(current_setting('test.cancel')::uuid)->>'status','updated','internal cancellation confirmed');
select is(public.get_mcp_shift_cancel_proposal(current_setting('test.cancel')::uuid)->>'status','updated','review shows result after confirmation');
select * from finish();
rollback;
